using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Person? p = JsonSerializer.Deserialize(json, info!);
    Console.WriteLine($"Deserialized: {p}");
}

// Probe for a type whose metadata may NOT be available.
// With the default resolver it will succeed, so we demonstrate the
// "not available" branch by using options that have NO resolver at all.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
{
    Console.WriteLine($"Unexpectedly resolved: {missing!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false — no resolver configured.");
}

public record Person(string Name, int Age);

